(() => {
  const style = document.createElement('style');
  style.id = 'wfgg-admin-enhancements-style';
  style.textContent = "/* WfGg Portal — administration members v0.4 */\n.wfgg-member-toolbar { display:grid; gap:12px; margin:14px 0 10px; padding:14px; border:1px solid var(--line); border-radius:18px; background:rgba(255,255,255,.025); }\n.wfgg-search-row { display:grid; grid-template-columns:minmax(0,1fr) auto; gap:9px; }\n.wfgg-search-box { display:flex; align-items:center; gap:8px; border:1px solid var(--line); border-radius:14px; background:rgba(9,7,12,.58); padding:0 12px; }\n.wfgg-search-box span { color:var(--accent-2); font-size:20px; transform:rotate(-20deg); }\n.wfgg-search-box input { border:0; background:transparent; padding:12px 0; }\n.wfgg-search-box input:focus { outline:0; }\n.wfgg-sort { width:auto; min-width:165px; }\n.wfgg-rank-chips { display:flex; gap:7px; overflow-x:auto; scrollbar-width:none; padding-bottom:2px; }\n.wfgg-rank-chips::-webkit-scrollbar { display:none; }\n.wfgg-rank-chips button, .wfgg-segmented button { white-space:nowrap; border:1px solid var(--line); background:rgba(255,255,255,.035); color:var(--muted); border-radius:999px; padding:7px 11px; font-size:12px; font-weight:800; cursor:pointer; }\n.wfgg-rank-chips button.active, .wfgg-segmented button.active { color:#fff; background:rgba(143,99,255,.22); border-color:rgba(178,150,255,.5); box-shadow:0 6px 18px rgba(143,99,255,.12); }\n.wfgg-status-row { display:flex; align-items:center; justify-content:space-between; gap:10px; }\n.wfgg-segmented { display:flex; gap:5px; }\n#wfggMemberSummary { color:var(--muted); white-space:nowrap; }\n.member-list { gap:10px; }\n.wfgg-member-card { border:1px solid var(--line); border-radius:17px; padding:11px; display:grid; grid-template-columns:auto minmax(0,1fr) auto; gap:11px; align-items:center; background:linear-gradient(145deg,rgba(255,255,255,.035),rgba(255,255,255,.015)); box-shadow:0 8px 26px rgba(0,0,0,.12); transition:border-color .15s ease, transform .15s ease, opacity .15s ease; }\n.wfgg-member-card:hover { border-color:rgba(178,150,255,.27); transform:translateY(-1px); }\n.wfgg-member-card.is-inactive { opacity:.55; }\n.wfgg-member-avatar { width:50px; height:50px; border-radius:50%; display:grid; place-items:center; background-color:rgba(143,99,255,.16); background-size:cover; background-position:center; border:2px solid rgba(178,150,255,.26); font-weight:900; flex:0 0 auto; }\n.wfgg-member-avatar.initials { color:#efe7ff; }\n.wfgg-member-copy { min-width:0; display:grid; gap:5px; }\n.wfgg-member-name-row { min-width:0; display:flex; align-items:baseline; gap:7px; flex-wrap:wrap; }\n.wfgg-member-name-row strong { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; font-size:15px; }\n.wfgg-member-name-row small { color:var(--muted); font-size:10px; }\n.wfgg-member-badges { display:flex; gap:5px; flex-wrap:wrap; }\n.wfgg-badge { display:inline-flex; align-items:center; min-height:21px; padding:3px 7px; border-radius:999px; font-size:10px; font-weight:900; letter-spacing:.02em; border:1px solid var(--line); background:rgba(255,255,255,.045); }\n.wfgg-badge.rank.R5 { color:#ffd97c; border-color:rgba(255,217,124,.32); background:rgba(255,190,60,.08); }\n.wfgg-badge.rank.R4 { color:#cdb8ff; border-color:rgba(178,150,255,.34); background:rgba(143,99,255,.1); }\n.wfgg-badge.office { color:#9ee9d0; border-color:rgba(142,230,187,.3); background:rgba(142,230,187,.07); }\n.wfgg-badge.owner { color:#ffe4a6; border-color:rgba(255,219,133,.42); background:linear-gradient(135deg,rgba(255,203,84,.12),rgba(143,99,255,.12)); }\n.wfgg-badge.inactive { color:#ff9ca9; border-color:rgba(255,124,141,.34); background:rgba(255,124,141,.08); }\n.wfgg-last-login { color:var(--muted); font-size:10px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }\n.wfgg-edit-member { border:1px solid var(--line); background:rgba(255,255,255,.055); border-radius:12px; padding:8px 10px; cursor:pointer; font-size:12px; font-weight:800; }\n.wfgg-edit-member:hover { border-color:rgba(178,150,255,.4); background:rgba(143,99,255,.1); }\n.wfgg-empty { padding:24px 12px; text-align:center; color:var(--muted); border:1px dashed var(--line); border-radius:16px; }\n.wfgg-create-hint { grid-column:1/-1; color:var(--muted); font-size:11px; line-height:1.4; margin:-2px 2px 2px; }\n.wfgg-admin-modal { position:fixed; inset:0; z-index:80; display:grid; place-items:center; padding:16px; background:rgba(5,4,8,.76); backdrop-filter:blur(10px); }\n.wfgg-admin-modal.hidden { display:none; }\n.wfgg-admin-dialog { width:min(520px,100%); max-height:min(88vh,820px); overflow:auto; position:relative; padding:22px; border-radius:24px; }\n.wfgg-modal-close { position:absolute; top:12px; right:12px; width:38px; height:38px; border:1px solid var(--line); background:rgba(255,255,255,.055); border-radius:50%; font-size:24px; cursor:pointer; }\n.wfgg-editor-head { display:flex; align-items:center; gap:13px; padding-right:38px; margin-bottom:18px; }\n.wfgg-editor-head .wfgg-member-avatar { width:62px; height:62px; }\n.wfgg-editor-head h3 { margin:0 0 6px; font-size:21px; }\n.wfgg-editor-grid { display:grid; grid-template-columns:1fr 1fr; gap:10px; }\n.wfgg-editor-grid label, .wfgg-code-field { display:grid; gap:7px; color:#ddd4e9; font-size:12px; font-weight:800; }\n.wfgg-active-toggle { display:flex; align-items:center; justify-content:space-between; gap:12px; margin:14px 0; padding:12px 13px; border:1px solid var(--line); border-radius:15px; background:rgba(255,255,255,.025); }\n.wfgg-active-toggle span { display:grid; gap:2px; }\n.wfgg-active-toggle small { color:var(--muted); font-weight:500; }\n.wfgg-active-toggle input { width:20px; height:20px; accent-color:var(--accent); }\n.wfgg-admin-note { color:var(--muted); font-size:12px; line-height:1.5; margin:12px 0; padding:10px 12px; border-radius:12px; background:rgba(143,99,255,.07); border:1px solid rgba(178,150,255,.15); }\n.wfgg-editor-actions { display:grid; grid-template-columns:1fr 1fr; gap:8px; margin-top:14px; }\n.wfgg-editor-actions .wfgg-leader-button { grid-column:1/-1; color:#ffe4a6; border-color:rgba(255,219,133,.28); }\n.wfgg-editor-message { margin-top:10px; padding:9px 11px; border-radius:11px; background:rgba(142,230,187,.09); color:var(--success); font-size:12px; }\n.wfgg-editor-message.error { background:rgba(255,124,141,.09); color:var(--danger); }\n.wfgg-new-code { margin:18px 0 12px; padding:17px; border-radius:16px; border:1px solid rgba(178,150,255,.35); background:rgba(9,7,12,.64); text-align:center; font-size:32px; font-weight:900; letter-spacing:.22em; }\n.wfgg-code-field { margin-top:16px; }\n@media (max-width:600px) {\n  .wfgg-search-row { grid-template-columns:1fr; }\n  .wfgg-sort { width:100%; }\n  .wfgg-status-row { align-items:flex-start; flex-direction:column; }\n  .wfgg-member-card { grid-template-columns:auto minmax(0,1fr); }\n  .wfgg-edit-member { grid-column:1/-1; width:100%; }\n  .wfgg-editor-grid { grid-template-columns:1fr; }\n  .wfgg-admin-modal { padding:0; align-items:end; }\n  .wfgg-admin-dialog { width:100%; border-radius:24px 24px 0 0; padding-bottom:calc(22px + env(safe-area-inset-bottom)); }\n}\n";
  document.head.appendChild(style);
})();
